// The gameplay collider is deliberately simpler than the art. Snap the heat
// stamp to the first visible triangle near the accepted contact, once per hit.
bool ProjectPrimaryContactToMesh(const ModelData& model, Matrix4x4 world, Vector3 origin,
    Vector3 direction, float& nearest, Vector3& point, Vector3& normal) {
    const auto inverse=Inverse(world);
    const auto localOrigin=RailCombatImpact::Transform(origin,inverse,1);
    const auto localVector=RailCombatImpact::Transform(direction,inverse,0);
    const auto transformedRay=XMVectorSet(localVector.x,localVector.y,localVector.z,0);
    const float localScale=XMVectorGetX(XMVector3Length(transformedRay));
    if(localScale<.00001f)return false;
    const auto ray=XMVectorScale(transformedRay,1/localScale);
    const auto start=XMVectorSet(localOrigin.x,localOrigin.y,localOrigin.z,1);
    const auto vertex=[&](size_t corner) {
        const auto& p=model.vertices[model.indices.empty()?corner:model.indices[corner]].position;
        return XMVectorSet(p.x,p.y,p.z,1);
    };
    const size_t count=model.indices.empty()?model.vertices.size():model.indices.size();
    bool found=false;
    for(size_t i=0;i+2<count;i+=3) {
        const auto a=vertex(i),b=vertex(i+1),c=vertex(i+2);
        float distance=0;
        if(!TriangleTests::Intersects(start,ray,a,b,c,distance) || distance>=nearest*localScale)continue;
        const auto face=XMVector3Normalize(XMVector3Cross(XMVectorSubtract(b,a),XMVectorSubtract(c,a)));
        XMFLOAT3 p{},n{};
        XMStoreFloat3(&p,XMVectorMultiplyAdd(ray,XMVectorReplicate(distance),start));
        XMStoreFloat3(&n,XMVectorGetX(XMVector3Dot(face,ray))>0?XMVectorNegate(face):face);
        nearest=distance/localScale;
        point={p.x,p.y,p.z};
        normal={n.x,n.y,n.z};
        found=true;
    }
    return found;
}

std::string HudUtf8(std::u8string_view text) {
    return {
        reinterpret_cast<const char*>(text.data()),
        reinterpret_cast<const char*>(text.data() + text.size())};
}

constexpr uint32_t kRailWatchdogStartFrame = 400;
constexpr DWORD kRailWatchdogStallMs = 3000;
constexpr double kRailGpuTimingLogThresholdMs = 10.0;
constexpr double kRailFramePacingLogThresholdMs = 8.0;
// One native atlas backs the lock-on HUD, Japanese gameplay text and the
// submission HUD.  Texture creation and every UV producer must share these
// dimensions; duplicating the old 256px height caused geometry to sample the
// Japanese glyph rows instead of the solid-white and marker cells.
constexpr uint32_t kRailHudAtlasWidth = 1024;
constexpr uint32_t kRailHudAtlasHeight = 2048;
// The font/marker region ends at y=512. Leave a transparent sampling gutter.
constexpr uint32_t kTitleLogoAtlasX = 32;
constexpr uint32_t kTitleLogoAtlasY = 544;
constexpr uint32_t kTitleLogoAtlasWidth = 960;
constexpr uint32_t kTitleLogoAtlasHeight = 640;
static_assert(kTitleLogoAtlasX+kTitleLogoAtlasWidth < kRailHudAtlasWidth &&
              kTitleLogoAtlasY+kTitleLogoAtlasHeight < kRailHudAtlasHeight);

struct RenderViewportMetrics {
    uint32_t width = 1;
    uint32_t height = 1;
    bool editorViewport = false;

    float AspectRatio() const {
        return height > 0
            ? static_cast<float>(width) / static_cast<float>(height)
            : 16.0f / 9.0f;
    }
};

RenderViewportMetrics ResolveRenderViewportMetrics(
    const editor::EditorViewportRenderTargetState& editorViewport,
    uint32_t windowWidth,
    uint32_t windowHeight) {
    if (editorViewport.enabled && editorViewport.Valid()) {
        return {
            editorViewport.renderWidth,
            editorViewport.renderHeight,
            true};
    }

    return {
        (std::max)(1u, windowWidth),
        (std::max)(1u, windowHeight),
        false};
}

std::atomic<bool> gRailWatchdogStarted{false};
std::atomic<uint32_t> gRailStageFrame{0};
std::atomic<DWORD> gRailStageTick{0};
std::atomic<const char*> gRailStageName{nullptr};

