    collisionFeedbackInput.listenerForward = {frameState_.viewMatrix.m[0][2],frameState_.viewMatrix.m[1][2],frameState_.viewMatrix.m[2][2]};
    collisionFeedbackInput.gameplayActive = vehicleDamageInput.gameplayActive;
